namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    private const int LoyaltyCapCents = 2_000;
    private const int LoyaltyMinimumSubtotalCents = 3_000;
    private const int WelcomeFiveCents = 500;
    private const int SummerTenPercent = 10;
    private const int SummerTenCapCents = 1_500;

    public static int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier, string? promoCode)
    {
        var loyaltyCents = LoyaltyCentsFor(subtotalCents, loyaltyTier);
        var promoCents = PromoCentsFor(promoCode, subtotalCents - loyaltyCents);

        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }

    private static int LoyaltyCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents < LoyaltyMinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyCapCents, LoyaltyDiscountPolicy.DiscountCentsFor(subtotalCents, loyaltyTier));

    private static int PromoCentsFor(string? promoCode, int remainingCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return WelcomeFiveCents;
        }

        return string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase)
            ? Math.Min(SummerTenCapCents, remainingCents * SummerTenPercent / 100)
            : 0;
    }
}

namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express
            ? ExpressFeeCents * Convert.ToInt32(loyaltyTier != LoyaltyTier.Platinum)
            : StandardFeeCentsFor(payableTotalCents, loyaltyTier);

    private static int StandardFeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier) =>
        loyaltyTier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}

